'use strict';
const { GenerationRecipeService, redact, SCHEMA_VERSION } = require('./service');
const { PersistentProductionRepository } = require('../persistence/production-repository');
const { PostgresRepository } = require('../persistence/postgres-repository');
function contractVersion(input){return input.providerContractVersion||input.providerContract?.version||process.env.FORGE_PROVIDER_CONTRACT_VERSION||'forge-stage-v1';}
async function buildRecipe(service,input){const episodeId=input.episodeId||input.context?.episodeId||input.job?.episode_id;let tenantId=input.tenantId||input.context?.tenantId;let projectId=input.projectId||input.context?.projectId;if(episodeId){const r=await service.pool.query('SELECT e.id,e.project_id,p.tenant_id FROM episodes e JOIN projects p ON p.id=e.project_id WHERE e.id=$1',[episodeId]);projectId=projectId||r.rows[0]?.project_id;tenantId=tenantId||r.rows[0]?.tenant_id;}if(!projectId||!tenantId)return null;const request=input.request||input.providerRequest||input.payload||{};const capability=String(input.capability||input.generationType||request.capability||'unknown');const provider=input.provider||{name:input.providerName||'unknown',model:input.model||null};const inputVersionIds=[...new Set(input.inputVersionIds||request.inputVersionIds||[])];const digests=inputVersionIds.length&&episodeId?(await service.pool.query('SELECT content_hash FROM version_records WHERE episode_id=$1 AND id=ANY($2::text[])',[episodeId,inputVersionIds])).rows.map(r=>r.content_hash).filter(Boolean):[];const prompt=request.prompt??request.text??request.content?.text??request.narration??'';return service.createSnapshot({tenantId,projectId,episodeId,recipeKey:input.recipeKey||`${episodeId||projectId}:${input.stage||input.operation||capability}`,capability,operation:input.operation||input.stage||capability,prompt,structuredInputs:redact(request),model:redact({...((input.model&&typeof input.model==='object')?input.model:{id:input.model||provider.model||null}),parameters:request.parameters||{}}),provider:redact({name:provider.name||'unknown',version:provider.version||null,releaseEpoch:provider.releaseEpoch||null}),providerContract:redact({version:contractVersion(input),decisionId:input.contractDecisionId||input.context?.contractDecisionId||null}),safetyPolicy:redact({version:input.policyVersion||input.context?.policyVersion||null,policy:input.policy||null}),deterministicParameters:redact(request.deterministicParameters||{seed:request.seed??null,temperature:request.temperature??null,topP:request.topP??request.top_p??null,topK:request.topK??request.top_k??null}),inputArtifactDigests:digests,templateId:request.templateId||null,templateVersion:request.templateVersion||null,templateHash:request.templateHash||null,workflowVersionId:request.workflowVersionId||input.workflowVersionId||null,workflowStage:input.stage||null,executionEpoch:request.executionEpoch||null,environment:{node:process.version,platform:process.platform,arch:process.arch,recipeSchema:SCHEMA_VERSION,providerContractVersion:contractVersion(input)},actor:input.actor||input.context?.actor||'generation-worker'});}
function installRepositoryHooks(){if(PersistentProductionRepository.prototype.__generationRecipeHook)return;PostgresRepository.prototype.createProviderRun=async function(input){return this.withTransaction(async(client)=>{const existing=await client.query('SELECT * FROM provider_runs WHERE idempotency_key=$1 FOR UPDATE',[input.idempotencyKey]);if(existing.rows[0])return existing.rows[0];return(await client.query(`INSERT INTO provider_runs (id,episode_id,capability,provider,model,input_version_ids,idempotency_key,request,attempt,generation_recipe_id) VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7,$8::jsonb,$9,$10) RETURNING *`,[input.id,input.episodeId,input.capability,input.provider,input.model||null,JSON.stringify(input.inputVersionIds||[]),input.idempotencyKey,JSON.stringify(input.request||{}),input.attempt||1,input.generationRecipeId||null])).rows[0];});};const original=PersistentProductionRepository.prototype.createProviderRun;PersistentProductionRepository.prototype.createProviderRun=async function(input){const capability=String(input.capability||'');const needs=['research','script','scene-plan','narration','assets','transcription','text-generation','image-generation','video-generation','tts','speech-synthesis'].includes(capability);if(!needs||input.generationRecipeId)return original.call(this,input);const service=new GenerationRecipeService({pool:this.db.pool});const recipe=await buildRecipe(service,{...input,provider:{name:input.provider,model:input.model}});if(!recipe)throw Object.assign(new Error('AI/media provider run requires tenant/project-scoped generation recipe context'),{code:'RECIPE_SCOPE_REQUIRED',statusCode:422});const run=await original.call(this,{...input,generationRecipeId:recipe.id});if(run?.id){try{await service.createAttempt({recipeId:recipe.id,tenantId:recipe.tenantId,projectId:recipe.projectId,providerRunId:run.id,idempotencyKey:`provider-run:${run.id}`,actor:input.actor||'generation-worker',observed:{provider:input.provider,model:input.model,contractVersion:contractVersion(input)}});}catch(error){if(error.code!=='IDEMPOTENCY_CONFLICT')throw error;}}return run;};PersistentProductionRepository.prototype.__generationRecipeHook=true;}
function installNarrationHook(){try{const narration=require('../narration/tts-worker');if(narration.executeNarration.__generationRecipeHook)return;const original=narration.executeNarration;const wrapped=async function(options={}){const pool=options.pool,episodeId=options.payload?.episodeId;if(!pool||!episodeId)return original(options);const row=(await pool.query('SELECT e.project_id,p.tenant_id FROM episodes e JOIN projects p ON p.id=e.project_id WHERE e.id=$1',[episodeId])).rows[0];if(!row)return original(options);const provider=options.providerRegistry?.get('tts')||null;const service=new GenerationRecipeService({pool});const scriptVersionId=options.payload?.scriptVersionId||options.payload?.inputVersionId||null;const script=scriptVersionId?(await pool.query('SELECT content_hash FROM version_records WHERE id=$1 AND episode_id=$2',[scriptVersionId,episodeId])).rows[0]:null;const recipe=await service.createSnapshot({tenantId:row.tenant_id,projectId:row.project_id,episodeId,recipeKey:`${episodeId}:narration`,capability:'tts',operation:'NARRATION',prompt:options.payload?.text||options.payload?.narration||'',structuredInputs:{scriptVersionId},model:{id:provider?.model||process.env.FORGE_TTS_MODEL||null,voice:options.payload?.voice||process.env.FORGE_TTS_VOICE||null},provider:{name:provider?.name||'configured-tts-command',version:provider?.version||null},providerContract:{version:process.env.FORGE_TTS_CONTRACT_VERSION||'forge-tts-v1'},deterministicParameters:{seed:options.payload?.seed??null,speed:options.payload?.speed??null},inputArtifactDigests:script?.content_hash?[script.content_hash]:[],actor:options.job?.actor||'narration-worker'});const attempt=await service.createAttempt({recipeId:recipe.id,tenantId:row.tenant_id,projectId:row.project_id,idempotencyKey:`narration:${options.job?.id||episodeId}:${recipe.recipeHash}`,jobId:options.job?.id||null,actor:options.job?.actor||'narration-worker',observed:{provider:provider?.name,model:provider?.model,recipeHash:recipe.recipeHash}});try{const result=await original({...options,payload:{...options.payload,recipeId:recipe.id}});await service.finishAttempt({attemptId:attempt.id,status:'SUCCEEDED',outputArtifactIds:[result?.artifactId].filter(Boolean)});return result;}catch(error){await service.finishAttempt({attemptId:attempt.id,status:error?.code==='CANCELLED'?'CANCELLED':'FAILED',error});throw error;}};wrapped.__generationRecipeHook=true;narration.executeNarration=wrapped;}catch(error){if(process.env.NODE_ENV!=='test')console.warn('Generation recipe narration hook unavailable:',error.message);}}
function install(){installRepositoryHooks();installNarrationHook();}
module.exports={install,buildRecipe};
